'use client'

import * as React from 'react'

// `./progress-bar` and not `../progress-bar/progress-bar`: see the note in
// ./progress-bar.ts. The installed layout is flat, so this is the path that is
// correct for a consumer, and the shim is what makes it correct here too.
import { ProgressBar, progressFraction } from './progress-bar'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Milestones, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './milestones.css'
import { LockGlyph, TickGlyph } from './glyphs'

/**
 * Milestones: the rewards that sit on a progress track.
 *
 * Specimen 3c. A run the player is travelling along, with the points on it
 * where something is waiting: a reward reached, the one they are on, and the
 * ones still locked.
 *
 * The track is a `progress-bar` rather than a second bar written here, so
 * there is one fill geometry, one set of state words and one way of expressing
 * how far through something is. BDS-022 makes `progress-bar` the base for this
 * component for that reason.
 *
 * There is no `data-gs-progress` and no `data-gs-fill`. How far along the track
 * the player is, is `data-gs-value` over `data-gs-max`, and a marker's position
 * is the same fraction resolved to a percentage in a custom property, which is
 * not an attribute: nothing selects on it and no test reads it as state.
 *
 * It performs nothing. It does not decide that a milestone is reached, unlock
 * one, or claim a reward. The host says which is which.
 */

export interface Milestone {
  /** The host's own id. Rides on `data-gs-milestone`. */
  id: string
  /** Where on the track it sits, in the same units as `value` and `max`. */
  at: number
  /** The word a player reads as this milestone's name. */
  label: string
  /** What rides inside the marker: a multiplier, a number, a mark. */
  children?: React.ReactNode
  /** Reached. The host decides; the component never infers it from the number. */
  complete?: boolean
  /** The one the player is working towards now. */
  active?: boolean
  /** Available later, not now. Keeps its shape and shows a padlock. */
  locked?: boolean
}

export interface MilestonesProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** The milestones, in any order. Position comes from `at`, not from the array. */
  milestones: Milestone[]
  /** How far along the track the player is. */
  value: number
  /** The end of the track. */
  max: number
  /** The floor the track counts from. Omitted from the DOM when it is zero. */
  min?: number
  /** The word a player reads as the track's name. */
  label?: string
}

/** From the contract's table of state words, so no component invents its own. */
const STATE_WORD = {
  complete: 'complete',
  active: 'current',
  locked: 'locked',
} as const



export function Milestones({
  milestones,
  value,
  max,
  min = 0,
  label = 'milestones',
  className,
  ...rest
}: MilestonesProps) {
  const reached = milestones.filter((m) => m.complete).length

  // The name carries the run, because a screen reader user gets no fill and no
  // marker. Order: what it is, then where it is.
  const words = [label, `${reached} of ${milestones.length} reached`]

  return (
    <div
      {...rest}
      className={['gs-milestones', className].filter(Boolean).join(' ')}
      data-gs-component="milestones"
      role="group"
      aria-label={words.join(', ')}
    >
      {/* The track is a real progress-bar, not a bar drawn again here. It
          keeps its own root marker, per the nesting rule: a selector for
          [data-gs-component="progress-bar"] inside a milestones is how a test
          asserts the track was composed rather than reimplemented. */}
      <ProgressBar
        className="gs-milestones__track"
        value={value}
        max={max}
        min={min}
        label={label}
        complete={max > min && value >= max}
        // The group's label above is the accessible name for the whole run, so
        // the bar inside it is decoration for a screen reader: announcing it
        // would read the position twice, once as a percentage and once as a
        // count of milestones.
        aria-hidden="true"
      />

      <div className="gs-milestones__list" data-gs-scope="milestones" data-gs-part="list" role="list">
        {milestones.map((milestone) => {
          const state = milestone.complete
            ? 'complete'
            : milestone.active
              ? 'active'
              : milestone.locked
                ? 'locked'
                : undefined
          const markerWords = [milestone.label]
          if (state) markerWords.push(STATE_WORD[state])
          return (
            <span
              key={milestone.id}
              className="gs-milestones__milestone"
              data-gs-scope="milestones" data-gs-part="milestone"
              // Rule 5 of the part vocabulary: a word may be both a part and an
              // attribute when the part is the element that renders that
              // attribute's value. This is that element.
              data-gs-milestone={milestone.id}
              data-gs-complete={milestone.complete ? 'true' : undefined}
              data-gs-active={milestone.active ? 'true' : undefined}
              data-gs-locked={milestone.locked ? 'true' : undefined}
              // The marker's colour and glow change; it does not travel. So
              // emphasis, and it survives reduced motion, which is the whole
              // reason a reached milestone also carries a tick.
              data-gs-animates="emphasis"
              role="listitem"
              aria-label={markerWords.join(', ')}
              // Not an attribute: CSS cannot divide one attribute by another,
              // so the fraction the marker's position needs travels as a custom
              // property, exactly as progress-bar's fill does.
              style={{ '--gs-milestone-at': `${progressFraction(milestone.at, min, max) * 100}%` } as React.CSSProperties}
            >
              {milestone.complete || milestone.locked ? (
                <span
                  className="gs-milestones__glyph"
                  data-gs-scope="milestones" data-gs-part="glyph"
                  data-gs-animates="emphasis"
                  aria-hidden="true"
                >
                  {milestone.complete ? <TickGlyph /> : <LockGlyph />}
                </span>
              ) : null}
              {milestone.children ? (
                <span className="gs-milestones__content" data-gs-scope="milestones" data-gs-part="label" aria-hidden="true">
                  {milestone.children}
                </span>
              ) : null}
            </span>
          )
        })}
      </div>
    </div>
  )
}

/* Milestones. Every value comes from a token; nothing here is a literal colour,
   size, duration or typeface.

   The track is a progress-bar and styles itself. Everything here is the markers
   and where they sit on it. Specimen 3c draws it and design/twins/3c.json
   measures ours against it: a 14px track, 32px discs for the milestones passed
   and the one still locked, and a 44px disc for the one being worked towards,
   all ringed at the control stroke in colour.edge and centred on the track. */

.gs-milestones {
  position: relative;
  display: grid;
  align-items: center;
  box-sizing: border-box;
  width: 100%;
  /* The markers sit centred on the track's ends, so half of each hangs
     outside it. The drawing gives the row 22px of margin either side, half
     the largest marker; ours pads by the same half so nothing is cut off. */
  padding-inline: calc(var(--gs-size-control-medium) / 2);
  /* Room for the largest marker, so it does not paint over the neighbour
     above or below. The drawing gives the row 56px; no token is that, and the
     marker's own height is what the row needs. */
  min-height: var(--gs-size-control-medium);
}

/* The bar and the markers occupy one cell, so the markers ride on the track
   rather than sitting under it. */
.gs-milestones__track,
.gs-milestones__list {
  grid-area: 1 / 1;
}

.gs-milestones__list {
  position: relative;
  height: 100%;
  pointer-events: none;
}

/* Positioned by the fraction the component resolved, which is a custom
   property and not an attribute: CSS cannot divide one attribute by another.

   A marker is the tick's own box, icon.utility, with space.2 round it: 32px,
   which is what the drawing draws and nine other places on the canvas draw,
   and no size token is. A marker carrying both a tick and an "x2" grows
   sideways rather than hiding one, so a reached milestone never says so in
   colour alone. */
.gs-milestones__milestone {
  position: absolute;
  top: 50%;
  left: var(--gs-milestone-at, 0%);
  transform: translate(-50%, -50%);

  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-1);
  box-sizing: border-box;

  min-width: calc(var(--gs-size-icon-utility) + 2 * var(--gs-space-2));
  height: calc(var(--gs-size-icon-utility) + 2 * var(--gs-space-2));
  padding-inline: var(--gs-space-1);
  border-radius: var(--gs-radius-full);

  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  line-height: 1;

  color: var(--gs-color-ink-secondary);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);

  /* Colour and glow only. A marker does not travel, so nothing here is timed
     as motion, and every state below stays readable under reduced motion. */
  transition:
    background var(--gs-motion-emphasis) ease-out,
    box-shadow var(--gs-motion-emphasis) ease-out;
}

/* -- reached -------------------------------------------------------------- */
/* Three channels: a solid fill, a tick, and the ring in edge rather than the
   surface's own. */
.gs-milestones__milestone[data-gs-complete='true'] {
  background: var(--gs-color-positive);
  color: var(--gs-color-on-bright);
}

/* -- the one being worked towards ----------------------------------------- */
/* Bigger as well as brighter, control.medium against the others' 32, so it
   reads as the current one at a glance and on a screen that has lost the hue.
   The drawing adds an 18px glow of the reward colour with no ring; no token
   draws that, and depth.reward's two hard rings are not what is drawn, so the
   size and the fill carry the state and the glow is requested in the twins
   file. The figure inside, "x2", is the drawing's 12px display face; figure is
   14 and the twins file carries the 2px. */
.gs-milestones__milestone[data-gs-active='true'] {
  min-width: var(--gs-size-control-medium);
  height: var(--gs-size-control-medium);
  background: var(--gs-color-reward);
  color: var(--gs-color-on-bright);
}

/* -- locked --------------------------------------------------------------- */
/* Keeps its shape and shows a padlock, the same distinction button draws
   between "not yet" and "not ever": the dark with a solid muted ring, the
   padlock in muted. Solid, not dashed: the drawing dashes the XP bar's next
   level and draws this marker's ring solid, and the padlock is what says
   locked here. */
.gs-milestones__milestone[data-gs-locked='true'] {
  background: var(--gs-color-edge);
  border-color: var(--gs-color-muted);
  color: var(--gs-color-muted);
}

.gs-milestones__glyph {
  display: flex;
  line-height: 1;
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

/* The mark here renders at about 12px, on the marker dot, where the shared glyph weight computes to
   less than a device pixel and greys out. Same drawing, heavier stroke. */
.gs-milestones__milestone .gs-glyph {
  stroke-width: var(--gs-stroke-glyph-small);
}
